head.script:
scwin.trigger1_onclick = function(e) {
    $w.executeSubmission("submission1");
};
scwin.submission1_submitdone = function(e) {
    if (dataMap1.get("success") == "success") {
        $w.url("subMission_URL_WPF-1528_(WSQ-2520)_sub.xml");
    }
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.logger.getErrorLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

